functions.longDescription:
Define a callback with opaque user context.

Example workflow — callback with user context:
```c
typedef void (*FrameCallback)(const unsigned char *frame, size_t size, void *context);

typedef struct Decoder
{
    FrameCallback onFrame;
    void *context;
} Decoder;

void Decoder_SetCallback(Decoder *decoder, FrameCallback callback, void *context)
{
    decoder->onFrame = callback;
    decoder->context = context;
}
```

Example workflow — callback registration with user data:
```c
typedef void (*EventCallback)(int eventCode, void *userData);

typedef struct EventSource
{
    EventCallback callback;
    void *userData;
} EventSource;

void EventSource_Notify(EventSource *source, int code)
{
    if (source->callback) source->callback(code, source->userData);
}
```

Example workflow — function pointer parameter + context:
```c
typedef void (*VisitFn)(int value, void *context);

void ForEachValue(const int *values, size_t count, VisitFn visit, void *context)
{
    for (size_t i = 0; i < count; ++i)
    {
        visit(values[i], context);
    }
}
```

Example workflow — void * user context cast in callback:
```c
typedef struct
{
    int panel;
    double scale;
} MyContext;

void OnEvent(int code, void *callbackData)
{
    MyContext *ctx = (MyContext *)callbackData;
    if (!ctx)
    {
        return;
    }

    printf("panel=%d scale=%f code=%d
", ctx->panel, ctx->scale, code);
}
```

Example workflow — CVI callbackData cast:
```c
typedef struct
{
    int deviceId;
    char label[32];
} CallbackContext;

int CVICALLBACK PanelCallback(int panel, int control, int event, void *callbackData, int eventData1, int eventData2)
{
    CallbackContext *ctx = (CallbackContext *)callbackData;

    switch (event)
    {
        case EVENT_COMMIT:
            if (ctx)
            {
                printf("control=%d device=%d label=%s
", control, ctx->deviceId, ctx->label);
            }
            break;
    }
    return 0;
}
```

