Windows COM-port setup normally combines CreateFileA, GetCommState, SetCommState and SetCommTimeouts.

Workflow examples retained from the previous pack:

```cpp
#ifdef _WIN32
#include <windows.h>
#include <stdexcept>

HANDLE serial = CreateFileW(
    L"\\\\.\\COM12",
    GENERIC_READ | GENERIC_WRITE,
    0,
    nullptr,
    OPEN_EXISTING,
    FILE_ATTRIBUTE_NORMAL,
    nullptr);

if (serial == INVALID_HANDLE_VALUE)
{
    throw std::runtime_error("Unable to open COM port");
}

DCB dcb{};
dcb.DCBlength = sizeof(dcb);
GetCommState(serial, &dcb);
dcb.BaudRate = CBR_115200;
dcb.ByteSize = 8;
dcb.Parity = NOPARITY;
dcb.StopBits = ONESTOPBIT;
SetCommState(serial, &dcb);
#endif
```

```cpp
#ifdef _WIN32
COMMTIMEOUTS timeouts{};
timeouts.ReadIntervalTimeout = 20;
timeouts.ReadTotalTimeoutConstant = 100;
timeouts.ReadTotalTimeoutMultiplier = 0;
timeouts.WriteTotalTimeoutConstant = 100;
SetCommTimeouts(serial, &timeouts);

DWORD written = 0;
WriteFile(serial, tx.data(), static_cast<DWORD>(tx.size()), &written, nullptr);

DWORD received = 0;
ReadFile(serial, rx.data(), static_cast<DWORD>(rx.size()), &received, nullptr);

CloseHandle(serial);
#endif
```

POSIX serial-port setup normally combines open, tcgetattr, cfsetispeed, cfsetospeed and tcsetattr.

Workflow examples retained from the previous pack:

```cpp
#ifndef _WIN32
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>

int serial = open("/dev/ttyUSB0", O_RDWR | O_NOCTTY);
termios tty{};
tcgetattr(serial, &tty);
cfsetispeed(&tty, B115200);
cfsetospeed(&tty, B115200);
tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
tty.c_cflag |= CLOCAL | CREAD;
tty.c_cflag &= ~(PARENB | CSTOPB | CRTSCTS);
tty.c_lflag = 0;
tty.c_iflag = 0;
tty.c_oflag = 0;
tcsetattr(serial, TCSANOW, &tty);
#endif
```

Synchronous libusb workflows remain easy to follow but block the caller. Keep event-loop or worker-thread considerations in mind.

Workflow examples retained from the previous pack:

```cpp
#include <libusb.h>
#include <stdexcept>

libusb_context *context = nullptr;
if (libusb_init(&context) != 0)
{
    throw std::runtime_error("libusb_init failed");
}

libusb_device_handle *device = libusb_open_device_with_vid_pid(context, 0x1234, 0x5678);
if (!device)
{
    libusb_exit(context);
    throw std::runtime_error("USB device not found");
}

libusb_claim_interface(device, 0);
```

```cpp
unsigned char buffer[512]{};
int transferred = 0;

const int result = libusb_bulk_transfer(
    device,
    0x81, // endpoint IN
    buffer,
    sizeof(buffer),
    &transferred,
    1000); // timeout ms

if (result != 0)
{
    HandleUsbError(result);
}
```

```cpp
unsigned char data[64]{};

const int transferred = libusb_control_transfer(
    device,
    LIBUSB_ENDPOINT_IN | LIBUSB_REQUEST_TYPE_VENDOR | LIBUSB_RECIPIENT_DEVICE,
    request,
    value,
    index,
    data,
    sizeof(data),
    1000);
```

```cpp
libusb_release_interface(device, 0);
libusb_close(device);
libusb_exit(context);
```

